-- Customer support tickets stay separate from staff-filed order complaints.
alter table public.support_tickets add column if not exists issue_type text not null default 'other';
alter table public.support_tickets add column if not exists photo_paths text[] not null default '{}';
alter table public.support_tickets add column if not exists updated_at timestamptz not null default now();
alter table public.support_tickets add column if not exists resolved_at timestamptz;
alter table public.support_tickets add column if not exists last_customer_read_at timestamptz;
alter table public.support_tickets alter column priority set default 'medium';
alter table public.support_tickets drop constraint if exists support_tickets_status_check;
alter table public.support_tickets add constraint support_tickets_status_check check(status in ('open','in_progress','resolved')) not valid;
create index if not exists support_tickets_user_created_idx on public.support_tickets(user_id,created_at desc);

create table if not exists public.support_ticket_events(
 id bigint generated by default as identity primary key,
 ticket_id bigint not null references public.support_tickets(id) on delete cascade,
 actor_id uuid not null references public.users(id),
 event_type text not null check(event_type in ('created','reply','status_changed','reopened')),
 comment text,
 is_internal boolean not null default false,
 created_at timestamptz not null default now()
);
create index if not exists support_ticket_events_ticket_idx on public.support_ticket_events(ticket_id,created_at);
alter table public.support_tickets enable row level security;
alter table public.support_ticket_events enable row level security;
drop policy if exists "customers read own tickets" on public.support_tickets;
create policy "customers read own tickets" on public.support_tickets for select to authenticated using(user_id=auth.uid());
drop policy if exists "customers read own support events" on public.support_ticket_events;
create policy "customers read own support events" on public.support_ticket_events for select to authenticated using(not is_internal and exists(select 1 from public.support_tickets t where t.id=ticket_id and t.user_id=auth.uid()));
drop policy if exists "staff read support events" on public.support_ticket_events;
create policy "staff read support events" on public.support_ticket_events for select to authenticated using(public.current_complaint_staff_role() in ('store_manager','super_admin'));
revoke insert,update,delete on public.support_tickets,public.support_ticket_events from anon,authenticated;
grant select on public.support_tickets,public.support_ticket_events to authenticated;

insert into storage.buckets(id,name,public) values('support-photos','support-photos',false) on conflict(id) do nothing;
drop policy if exists "customers upload own support photos" on storage.objects;
create policy "customers upload own support photos" on storage.objects for insert to authenticated with check(bucket_id='support-photos' and (storage.foldername(name))[1]='support' and (storage.foldername(name))[2]=auth.uid()::text);
drop policy if exists "support participants read photos" on storage.objects;
create policy "support participants read photos" on storage.objects for select to authenticated using(bucket_id='support-photos' and (storage.foldername(name))[1]='support' and ((storage.foldername(name))[2]=auth.uid()::text or public.current_complaint_staff_role() in ('store_manager','super_admin')));
drop policy if exists "customers delete own support photos" on storage.objects;
create policy "customers delete own support photos" on storage.objects for delete to authenticated using(bucket_id='support-photos' and (storage.foldername(name))[1]='support' and (storage.foldername(name))[2]=auth.uid()::text);

drop function if exists public.customer_create_support_ticket(text,text,text,bigint);
drop function if exists public.customer_list_support_tickets();
create function public.customer_create_support_ticket(p_subject text,p_message text,p_order_id bigint,p_issue_type text,p_photo_paths text[] default '{}') returns bigint language plpgsql security definer set search_path=public as $$
declare v_id bigint; v_order public.orders%rowtype; v_priority text:='medium'; v_manager record;
begin
 if auth.uid() is null then raise exception 'AUTH_REQUIRED'; end if;
 if length(trim(coalesce(p_subject,'')))<5 or length(trim(coalesce(p_subject,'')))>120 then raise exception 'INVALID_SUBJECT'; end if;
 if length(trim(coalesce(p_message,'')))<20 or length(p_message)>1000 then raise exception 'INVALID_MESSAGE'; end if;
 if p_issue_type not in ('late_delivery','wrong_update','change_address_slot','payment_problem','delivered_damaged','wrong_item','missing_item','quality_problem','invoice_problem','refund_not_received','cancelled_without_request','account_login','payment_coupon','product_question','other') then raise exception 'INVALID_ISSUE_TYPE'; end if;
 if p_order_id is not null then select * into v_order from public.orders where id=p_order_id and user_id=auth.uid(); if not found then raise exception 'ORDER_NOT_FOUND'; end if; end if;
 if cardinality(coalesce(p_photo_paths,'{}'))>3 then raise exception 'TOO_MANY_PHOTOS'; end if;
 if exists(select 1 from unnest(coalesce(p_photo_paths,'{}')) x(path) where path not like 'support/'||auth.uid()::text||'/%' or not exists(select 1 from storage.objects so where so.bucket_id='support-photos' and so.name=x.path)) then raise exception 'INVALID_SUPPORT_PHOTO'; end if;
 if p_issue_type in ('wrong_item','delivered_damaged') then v_priority:='high';
 elsif p_issue_type='late_delivery' and v_order.status='out_for_delivery' and v_order.created_at<now()-interval '2 hours' then v_priority:='high'; end if;
 perform pg_advisory_xact_lock(hashtextextended(auth.uid()::text||':'||coalesce(p_order_id::text,'general')||':'||p_issue_type,0));
 if exists(select 1 from public.support_tickets t where t.user_id=auth.uid() and t.order_id is not distinct from p_order_id and t.issue_type=p_issue_type and t.status in ('open','in_progress')) then raise exception 'DUPLICATE_OPEN_SUPPORT_TICKET'; end if;
 insert into public.support_tickets(user_id,order_id,subject,message,priority,status,issue_type,photo_paths) values(auth.uid(),p_order_id,trim(p_subject),trim(p_message),v_priority,'open',p_issue_type,coalesce(p_photo_paths,'{}')) returning id into v_id;
 insert into public.support_ticket_events(ticket_id,actor_id,event_type,comment) values(v_id,auth.uid(),'created',trim(p_message));
 for v_manager in select u.id from public.users u join public.roles r on r.id=u.role_id where r.name::text in ('store_manager','super_admin') loop
   insert into public.notifications(user_id,recipient_user_id,type,title,message,body,order_id,complaint_id) values(v_manager.id,v_manager.id,'complaint_raised','New customer complaint','Customer complaint #'||v_id||case when p_order_id is null then ' · Account support' else ' · Order #'||p_order_id end||' needs review.','Customer complaint #'||v_id||case when p_order_id is null then ' · Account support' else ' · Order #'||p_order_id end||' needs review.',p_order_id,null);
 end loop;
 return v_id;
end $$;

create function public.customer_list_support_tickets() returns jsonb language plpgsql security definer set search_path=public as $$
declare result jsonb;
begin
 if auth.uid() is null then raise exception 'AUTH_REQUIRED'; end if;
 select coalesce(jsonb_agg(jsonb_build_object('ticket_id',t.id,'order_id',t.order_id,'subject',t.subject,'message',t.message,'priority',t.priority,'status',t.status,'issue_type',t.issue_type,'photo_paths',t.photo_paths,'created_at',t.created_at,'updated_at',t.updated_at,'last_customer_read_at',t.last_customer_read_at,'new_reply',exists(select 1 from public.support_ticket_events e where e.ticket_id=t.id and e.event_type='reply' and not e.is_internal and e.actor_id<>auth.uid() and e.created_at>coalesce(t.last_customer_read_at,'-infinity'::timestamptz)),'events',(select coalesce(jsonb_agg(jsonb_build_object('id',e.id,'event_type',e.event_type,'comment',e.comment,'created_at',e.created_at,'actor_name',coalesce(nullif(u.full_name,''),'Customer'),'actor_role',case when e.actor_id=auth.uid() then 'You' else 'Customer care' end) order by e.created_at),'[]'::jsonb) from public.support_ticket_events e left join public.users u on u.id=e.actor_id where e.ticket_id=t.id and not e.is_internal)) order by t.created_at desc),'[]'::jsonb) into result from public.support_tickets t where t.user_id=auth.uid();
 return result;
end $$;

create function public.customer_mark_support_ticket_read(p_ticket_id bigint) returns boolean language plpgsql security definer set search_path=public as $$
begin update public.support_tickets set last_customer_read_at=now() where id=p_ticket_id and user_id=auth.uid(); if not found then raise exception 'TICKET_NOT_FOUND'; end if; return true; end $$;

create function public.customer_reply_support_ticket(p_ticket_id bigint,p_message text) returns boolean language plpgsql security definer set search_path=public as $$
declare t public.support_tickets%rowtype; m record;
begin
 if length(trim(coalesce(p_message,'')))<1 or length(p_message)>1000 then raise exception 'INVALID_MESSAGE'; end if;
 select * into t from public.support_tickets where id=p_ticket_id and user_id=auth.uid() for update;
 if not found then raise exception 'TICKET_NOT_FOUND'; end if;
 if t.status='resolved' then raise exception 'TICKET_RESOLVED'; end if;
 insert into public.support_ticket_events(ticket_id,actor_id,event_type,comment) values(t.id,auth.uid(),'reply',trim(p_message));
 update public.support_tickets set updated_at=now() where id=t.id;
 for m in select u.id from public.users u join public.roles r on r.id=u.role_id where r.name::text in ('store_manager','super_admin') loop insert into public.notifications(user_id,recipient_user_id,type,title,message,body,order_id,complaint_id) values(m.id,m.id,'complaint_updated','Customer replied to complaint','Complaint #'||t.id||' has a new customer reply.','Complaint #'||t.id||' has a new customer reply.',t.order_id,null); end loop;
 return true;
end $$;

create function public.customer_reopen_support_ticket(p_ticket_id bigint) returns boolean language plpgsql security definer set search_path=public as $$
declare t public.support_tickets%rowtype;
begin select * into t from public.support_tickets where id=p_ticket_id and user_id=auth.uid() for update; if not found then raise exception 'TICKET_NOT_FOUND'; end if; if t.status<>'resolved' then raise exception 'TICKET_NOT_RESOLVED'; end if; update public.support_tickets set status='open',resolved_at=null,updated_at=now() where id=t.id; insert into public.support_ticket_events(ticket_id,actor_id,event_type,comment) values(t.id,auth.uid(),'reopened','Customer reopened this complaint.'); insert into public.notifications(user_id,recipient_user_id,type,title,message,body,order_id,complaint_id) select u.id,u.id,'complaint_raised','Customer reopened a complaint','Complaint #'||t.id||' was reopened.','Complaint #'||t.id||' was reopened.',t.order_id,null from public.users u join public.roles ro on ro.id=u.role_id where ro.name::text in ('store_manager','super_admin'); return true; end $$;

create function public.admin_list_customer_support_tickets() returns table(ticket_id bigint,order_id bigint,customer_name text,customer_email text,issue_type text,severity text,status text,created_at timestamptz,updated_at timestamptz,raised_by uuid,raised_by_name text,notes text,current_order_status text) language plpgsql security definer set search_path=public as $$
begin
 if public.current_complaint_staff_role() not in ('store_manager','super_admin') then raise exception 'COMPLAINT_ACCESS_REQUIRED' using errcode='42501'; end if;
 return query select t.id::bigint,t.order_id::bigint,coalesce(nullif(u.full_name::text,''),a.email::text,'Customer')::text,coalesce(a.email::text,'')::text,t.issue_type::text,t.priority::text,t.status::text,t.created_at::timestamptz,t.updated_at::timestamptz,t.user_id::uuid,coalesce(nullif(u.full_name::text,''),a.email::text,'Customer')::text,t.message::text,coalesce(o.status::text,'not_applicable')::text from public.support_tickets t left join public.orders o on o.id=t.order_id left join public.users u on u.id=t.user_id left join auth.users a on a.id=t.user_id order by t.created_at desc;
end $$;

create function public.admin_customer_support_ticket_detail(p_ticket_id bigint) returns jsonb language plpgsql security definer set search_path=public as $$
declare result jsonb;
begin
 if public.current_complaint_staff_role() not in ('store_manager','super_admin') then raise exception 'COMPLAINT_ACCESS_REQUIRED' using errcode='42501'; end if;
 select jsonb_build_object('ticket',to_jsonb(t)||jsonb_build_object('raised_by_name',coalesce(nullif(u.full_name,''),a.email,'Customer')),'order',case when o.id is null then jsonb_build_object('order_id',null,'status','not_applicable','created_at',null,'customer_name',coalesce(nullif(u.full_name,''),a.email,'Customer'),'email',coalesce(a.email,''),'phone',u.phone,'address',null,'delivery_slot',null,'total',null,'payment_status',null,'items','[]'::jsonb) else jsonb_build_object('order_id',o.id,'status',o.status,'created_at',o.created_at,'customer_name',coalesce(nullif(u.full_name,''),a.email,'Customer'),'email',coalesce(a.email,''),'phone',u.phone,'address',concat_ws(', ',ad.line1,ad.city,ad.postal_code),'delivery_slot',o.delivery_slot,'total',o.total,'payment_status',pay.status,'items',coalesce(items.rows,'[]'::jsonb)) end,'events',(select coalesce(jsonb_agg(jsonb_build_object('id',e.id,'event_type',e.event_type,'comment',e.comment,'is_internal',e.is_internal,'created_at',e.created_at,'actor_name',coalesce(nullif(eu.full_name,''),ea.email,'Staff'),'actor_role',coalesce(er.name::text,'Staff')) order by e.created_at),'[]'::jsonb) from public.support_ticket_events e left join public.users eu on eu.id=e.actor_id left join auth.users ea on ea.id=e.actor_id left join public.roles er on er.id=eu.role_id where e.ticket_id=t.id),'order_history','[]'::jsonb)
 into result from public.support_tickets t left join public.users u on u.id=t.user_id left join auth.users a on a.id=t.user_id left join public.orders o on o.id=t.order_id left join public.addresses ad on ad.id=o.address_id left join lateral(select string_agg(distinct p.status,', ' order by p.status) status from public.payments p where p.order_id=o.id)pay on true left join lateral(select coalesce(jsonb_agg(jsonb_build_object('name',p.name,'quantity',oi.quantity,'price',oi.unit_price) order by oi.id),'[]'::jsonb) rows from public.order_items oi join public.products p on p.id=oi.product_id where oi.order_id=o.id)items on true where t.id=p_ticket_id;
 if result is null then raise exception 'TICKET_NOT_FOUND'; end if; return result;
end $$;

create function public.admin_update_customer_support_ticket(p_ticket_id bigint,p_status text default null,p_comment text default null,p_internal boolean default false,p_resolution_note text default null) returns boolean language plpgsql security definer set search_path=public as $$
declare t public.support_tickets%rowtype; changed boolean:=false;
begin
 if public.current_complaint_staff_role() not in ('store_manager','super_admin') then raise exception 'MANAGER_REQUIRED' using errcode='42501'; end if;
 if p_status is not null and p_status not in ('open','in_progress','resolved') then raise exception 'INVALID_STATUS'; end if;
 if p_status='resolved' and nullif(trim(p_resolution_note),'') is null then raise exception 'RESOLUTION_NOTE_REQUIRED'; end if;
 select * into t from public.support_tickets where id=p_ticket_id for update; if not found then raise exception 'TICKET_NOT_FOUND'; end if;
 if p_status is not null and p_status is distinct from t.status then update public.support_tickets set status=p_status,resolved_at=case when p_status='resolved' then now() else null end,updated_at=now() where id=t.id; insert into public.support_ticket_events(ticket_id,actor_id,event_type,comment,is_internal) values(t.id,auth.uid(),'status_changed',p_status||case when p_status='resolved' then ': '||trim(p_resolution_note) else '' end,false); changed:=true; end if;
 if nullif(trim(coalesce(p_comment,'')),'') is not null then insert into public.support_ticket_events(ticket_id,actor_id,event_type,comment,is_internal) values(t.id,auth.uid(),'reply',left(trim(p_comment),1000),coalesce(p_internal,false)); update public.support_tickets set updated_at=now() where id=t.id; if not coalesce(p_internal,false) then changed:=true; end if; end if;
 if changed then insert into public.notifications(user_id,recipient_user_id,type,title,message,body,order_id,complaint_id) values(t.user_id,t.user_id,'complaint_updated','Support ticket update','Complaint #'||t.id||' has a new update.','Complaint #'||t.id||' has a new update.',t.order_id,null); end if;
 return true;
end $$;

grant execute on function public.customer_create_support_ticket(text,text,bigint,text,text[]) to authenticated;
grant execute on function public.customer_list_support_tickets() to authenticated;
grant execute on function public.customer_mark_support_ticket_read(bigint) to authenticated;
grant execute on function public.customer_reply_support_ticket(bigint,text) to authenticated;
grant execute on function public.customer_reopen_support_ticket(bigint) to authenticated;
grant execute on function public.admin_list_customer_support_tickets() to authenticated;
grant execute on function public.admin_customer_support_ticket_detail(bigint) to authenticated;
grant execute on function public.admin_update_customer_support_ticket(bigint,text,text,boolean,text) to authenticated;
do $$ begin if exists(select 1 from pg_publication where pubname='supabase_realtime') then if not exists(select 1 from pg_publication_tables where pubname='supabase_realtime' and schemaname='public' and tablename='support_ticket_events') then alter publication supabase_realtime add table public.support_ticket_events; end if; end if; end $$;
notify pgrst,'reload schema';

revoke all on function public.customer_create_support_ticket(text,text,bigint,text,text[]) from public,anon;
revoke all on function public.customer_list_support_tickets() from public,anon;
revoke all on function public.customer_mark_support_ticket_read(bigint) from public,anon;
revoke all on function public.customer_reply_support_ticket(bigint,text) from public,anon;
revoke all on function public.customer_reopen_support_ticket(bigint) from public,anon;
revoke all on function public.admin_list_customer_support_tickets() from public,anon;
revoke all on function public.admin_customer_support_ticket_detail(bigint) from public,anon;
revoke all on function public.admin_update_customer_support_ticket(bigint,text,text,boolean,text) from public,anon;
